def calculate_rsi(ticker: str, period: int = 14, start_date: str = None, end_date: str = None) -> dict:
    """Calculate RSI technical indicator."""
    import pandas as pd

    df = _load_data()

    if start_date and end_date:
        stock_data = df[(df["Ticker"] == ticker) & (df["Date"] >= start_date) & (df["Date"] <= end_date)].sort_values("Date")
    else:
        stock_data = df[df["Ticker"] == ticker].sort_values("Date")

    if stock_data.empty or len(stock_data) < period + 1:
        return {"error": "Insufficient data for RSI calculation"}

    # Calculate price changes
    delta = stock_data["Close"].diff()
    gain = (delta.where(delta > 0, 0)).rolling(window=period).mean()
    loss = (-delta.where(delta < 0, 0)).rolling(window=period).mean()

    rs = gain / loss
    rsi = 100 - (100 / (1 + rs))

    current_rsi = float(rsi.iloc[-1])

    # Interpretation
    if current_rsi > 70:
        signal = "Overbought"
    elif current_rsi < 30:
        signal = "Oversold"
    else:
        signal = "Neutral"

    return {
        "ticker": ticker,
        "rsi_period": period,
        "current_rsi": current_rsi,
        "signal": signal,
        "date": str(stock_data.iloc[-1]["Date"])
    }

