def get_weekly_summary(ticker: str, start_date: str, end_date: str) -> dict:
    """Aggregate daily data into weekly summary."""
    import pandas as pd

    df = _load_data()
    stock_data = df[(df["Ticker"] == ticker) & (df["Date"] >= start_date) & (df["Date"] <= end_date)].copy()

    if stock_data.empty:
        return {"error": "No data available"}

    stock_data["Date"] = pd.to_datetime(stock_data["Date"])
    stock_data.set_index("Date", inplace=True)

    # Resample to weekly
    weekly = stock_data.resample('W').agg({
        "Open": "first",
        "High": "max",
        "Low": "min",
        "Close": "last",
        "Volume": "sum"
    }).dropna()

    weekly_data = []
    for date, row in weekly.iterrows():
        weekly_data.append({
            "week_ending": str(date.date()),
            "open": float(row["Open"]),
            "high": float(row["High"]),
            "low": float(row["Low"]),
            "close": float(row["Close"]),
            "volume": int(row["Volume"])
        })

    return {
        "ticker": ticker,
        "period": f"{start_date} to {end_date}",
        "total_weeks": len(weekly_data),
        "weekly_data": weekly_data
    }

