            avg_by_day[day] = {
                "avg_return_pct": float(day_returns['mean'][day]),
                "occurrences": int(day_returns['count'][day])
            }

    return {
        "ticker": ticker,
        "period": f"{start_date} to {end_date}",
        "average_returns_by_day": avg_by_day
    }

